body.script:
//
(function () {
  "use strict";
  var esc = function (s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };
  var DAYS = ["dimanche","lundi","mardi","mercredi","jeudi","vendredi","samedi"];
  var MO = ["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
  function pad(n){ return (n < 10 ? "0" : "") + n; }
  function tick(){
    var d = new Date(), c = document.getElementById("clock");
    if (c) c.textContent = pad(d.getHours())+":"+pad(d.getMinutes())+":"+pad(d.getSeconds());
    var dt = document.getElementById("date");
    if (dt) dt.textContent = DAYS[d.getDay()]+" "+d.getDate()+" "+MO[d.getMonth()]+" "+d.getFullYear();
  }
  tick(); setInterval(tick, 1000);

  /* Thème persistant (09/08, Patrick) : même clé que l'accueil. */
  (function () {
    var root = document.documentElement, key = "tour-theme";
    var saved = null; try { saved = localStorage.getItem(key); } catch (e) {}
    if (saved === "light" || saved === "dark") { root.setAttribute("data-theme", saved); } else { root.setAttribute("data-theme", "light"); }
    document.getElementById("themebtn").addEventListener("click", function () {
      var cur = root.getAttribute("data-theme");
      if (!cur) cur = "light";
      var next = cur === "dark" ? "light" : "dark";
      root.setAttribute("data-theme", next);
      try { localStorage.setItem(key, next); } catch (e) {}
    });
  })();

  function render(d) {
    if (!d || d.error) {
      var n = document.getElementById("note");
      if (n) { n.hidden = false; n.textContent = d && d.error || "robine indisponible"; }
      return;
    }
    var st = document.getElementById("soustitre");
    if (st) st.textContent = d.nb_garde_fous + " garde-fous · " + d.nb_actifs +
      " actifs · " + d.nb_gabarits + " circuits";

    var strips = document.getElementById("strips");
    if (strips) {
      strips.innerHTML =
        '<div class="strip ok"><div class="lbl">Garde-fous</div><div class="val">' + d.nb_garde_fous + '</div></div>' +
        '<div class="strip ok"><div class="lbl">Actifs</div><div class="val">' + d.nb_actifs + '</div></div>' +
        '<div class="strip blue"><div class="lbl">Circuits sécurité</div><div class="val">' + d.nb_gabarits + '</div></div>';
    }

    var porte = document.getElementById("porte");
    if (porte) {
      var tunnel = (d.gabarits || []).filter(function (g) { return /tunnel/i.test(g.name); })[0];
      if (tunnel) {
        porte.innerHTML = '<b>' + esc(tunnel.name) + '</b><br>' +
          (tunnel.portes || []).map(function (p) {
            return '<span class="porte"><b>' + esc(p.nom) + "</b> — " + esc(p.agent) + "</span>";
          }).join("");
      } else {
        porte.innerHTML = '<span class="empty">gabarit « Tunnel de test » introuvable</span>';
      }
    }

    var tb = document.getElementById("garde-fous");
    if (tb) {
      tb.innerHTML = (d.garde_fous || []).map(function (g) {
        return "<tr><td class='mono'>" + esc(g.code) + "</td><td>" + esc(g.zone) +
          "</td><td><span class='tag " + esc(g.etat) + "'>" + esc(g.etat) + "</span></td><td>" +
          (g.actif ? "✅" : "⛔") + "</td><td>" + esc(g.crainte) + "</td></tr>";
      }).join("") || '<tr><td colspan="5" class="empty">(aucun garde-fou)</td></tr>';
    }

    var circ = document.getElementById("circuits");
    if (circ) {
      circ.innerHTML = (d.gabarits || []).map(function (g) {
        return '<div style="margin-bottom:10px"><b>' + esc(g.name) + "</b> " +
          '<span class="tag en_place">' + esc(g.type) + "</span><br>" +
          (g.portes || []).map(function (p) {
            return '<span class="porte"><b>' + esc(p.nom) + "</b> — " + esc(p.agent) + "</span>";
          }).join("") + "</div>";
      }).join("") || '<span class="empty">(aucun circuit)</span>';
    }
  }

  fetch("/tour/cockpit/data-securite", { credentials: "same-origin" })
    .then(function (r) { return r.json(); })
    .then(render)
    .catch(function () {
      var n = document.getElementById("note");
      if (n) { n.hidden = false; n.textContent = "Le robinet ne répond pas."; }
    });
})();
//

//
(function () {
  "use strict";
  var esc = function (s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };
  var DAYS = ["dimanche","lundi","mardi","mercredi","jeudi","vendredi","samedi"];
  var MO = ["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
  function pad(n){ return (n < 10 ? "0" : "") + n; }
  function tick(){
    var d = new Date(), c = document.getElementById("clock");
    if (c) c.textContent = pad(d.getHours())+":"+pad(d.getMinutes())+":"+pad(d.getSeconds());
    var dt = document.getElementById("date");
    if (dt) dt.textContent = DAYS[d.getDay()]+" "+d.getDate()+" "+MO[d.getMonth()]+" "+d.getFullYear();
  }
  tick(); setInterval(tick, 1000);

  /* Thème persistant (09/08, Patrick) : même clé que l'accueil. */
  (function () {
    var root = document.documentElement, key = "tour-theme";
    var saved = null; try { saved = localStorage.getItem(key); } catch (e) {}
    if (saved === "light" || saved === "dark") { root.setAttribute("data-theme", saved); } else { root.setAttribute("data-theme", "light"); }
    document.getElementById("themebtn").addEventListener("click", function () {
      var cur = root.getAttribute("data-theme");
      if (!cur) cur = "light";
      var next = cur === "dark" ? "light" : "dark";
      root.setAttribute("data-theme", next);
      try { localStorage.setItem(key, next); } catch (e) {}
    });
  })();

  var note = document.getElementById("note");
  function defaut(s) {
    if (note) { note.hidden = false; note.textContent = s || "action terminée"; }
    setTimeout(function(){ if (note) note.hidden = true; }, 6000);
  }

  function get(route, cible) {
    fetch(route).then(function (r) { return r.json(); }).then(function (d) {
      if (d && d.error) { defaut(d.error); return; }
      var el = document.getElementById(cible);
      if (el) el.textContent = d.sortie || "(vide)";
    }).catch(function () { defaut("service de défense indisponible"); });
  }

  function post(route, lib) {
    if (!window.confirm(lib + " ? Confirmer l'action.")) return;
    var boutons = document.querySelectorAll("#actions button");
    for (var i = 0; i < boutons.length; i++) boutons[i].disabled = true;
    var corps = { jeton: window.DEFENSE_JETON || "" };
    fetch(route, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(corps) })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (!d.ok) { defaut(d.error || "action refusée"); return; }
        defaut(lib + " : terminé");
        var el = document.getElementById("etat");
        if (el && d.sortie) el.textContent = d.sortie;
        get("/tour/cockpit/data-defense", "etat");
      })
      .catch(function () { defaut("service de défense indisponible"); })
      .then(function () {
        for (var j = 0; j < boutons.length; j++) boutons[j].disabled = false;
      });
  }

  document.getElementById("b-simuler").addEventListener("click", function () {
    get("/tour/cockpit/data-defense?action=simuler", "simuler");
  });
  document.getElementById("b-scan").addEventListener("click", function () {
    get("/tour/cockpit/data-defense?action=scan", "carte");
  });
  document.getElementById("b-connexions").addEventListener("click", function () {
    get("/tour/cockpit/data-defense?action=connexions", "carte");
  });
  document.getElementById("b-verrouiller").addEventListener("click", function () {
    post("/tour/cockpit/defense-action", "🔒 Verrouiller");
  });
  document.getElementById("b-deverrouiller").addEventListener("click", function () {
    post("/tour/cockpit/defense-action?action=deverrouiller", "🔓 Déverrouiller");
  });
  document.getElementById("b-isoler").addEventListener("click", function () {
    post("/tour/cockpit/defense-action?action=isoler-pi", "🛑 Isoler le Pi");
  });
  document.getElementById("b-relier").addEventListener("click", function () {
    post("/tour/cockpit/defense-action?action=relier-pi", "🔗 Relier le Pi");
  });

  function renderEtat(d) {
    if (!d || d.error) { defaut(d.error || "service indisponible"); return; }
    var st = document.getElementById("soustitre");
    if (st) st.textContent = "verrou : " + (d.verrou || "?") + " · Pi : " + (d.pi || "?");
    var lab = document.getElementById("etiquette");
    if (lab) {
      var v = (d.verrou || "").toLowerCase().indexOf("verrou") === 0;
      lab.textContent = v ? "VERROUILLÉ" : "NORMAL";
      lab.className = "tag " + (v ? "verrouille" : "normal");
    }
    var strips = document.getElementById("strips");
    if (strips) {
      strips.innerHTML =
        '<div class="strip ' + (d.verrou && d.verrou.indexOf("VERROU") === 0 ? "crit" : "ok") + '"><div class="lbl">Verrou</div><div class="val">' + esc(d.verrou || "?") + '</div></div>' +
        '<div class="strip ' + (d.pi && d.pi.indexOf("ISOLÉ") === 0 ? "crit" : "ok") + '"><div class="lbl">Raspberry Pi</div><div class="val">' + esc(d.pi || "?") + '</div></div>';
    }
    var nav = document.getElementById("nav-etat");
    if (nav) {
      nav.innerHTML = (d.connexions || []).map(function (c) {
        return '<span class="b"><b>' + esc(c[0]) + '</b> ' + esc(c[1]) + '</span>';
      }).join("");
    }
    var el = document.getElementById("etat");
    if (el) el.textContent = d.texte || "";
  }

  function refreshEtat() {
    fetch("/tour/cockpit/data-defense").then(function (r) { return r.json(); })
      .then(renderEtat).catch(function () { defaut("service de défense indisponible"); });
  }
  refreshEtat();
  setInterval(refreshEtat, 15000);
})();
//
